/* Vector apparatus: viewBox coordinates, no external images, no canvas blur. */
(()=>{'use strict';
const C={ink:'#e4eee8',muted:'#9fb9b0',line:'#54796b',mint:'#c6f18b',blue:'#78cddd',amber:'#ffbf79',pink:'#e0a5cf'};
const fmt=n=>Number.isFinite(n)?(Math.abs(n)<.01&&n!==0?n.toExponential(1):Number(n.toFixed(2)).toString()):'—';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const line=(x1,y1,x2,y2,color=C.line,extra='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="2" ${extra}/>`;
const arrow=(x1,y1,x2,y2,color=C.mint,dash=false)=>line(x1,y1,x2,y2,color,`marker-end="url(#labArrow)" ${dash?'stroke-dasharray="6 5"':''}`);
const text=(x,y,s,color=C.muted,size=13)=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" font-family="system-ui,sans-serif">${esc(s)}</text>`;
const circle=(x,y,r=10,color=C.mint)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const rect=(x,y,w,h,color,extra='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="5" fill="${color}" ${extra}/>`;
const path=(d,color=C.mint,extra='')=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="2.5" ${extra}/>`;
const spring=(x1,x2,y)=>path(`M${x1} ${y} L${x1+10} ${y} `+Array.from({length:16},(_,i)=>`L${x1+15+(x2-x1-30)*i/15} ${y+(i%2?10:-10)}`).join(' ')+` L${x2} ${y}`);
function wavePath(fn,x0=45,x1=555,y0=160,scale=65){return Array.from({length:241},(_,i)=>{const x=i/240;return`${i?'L':'M'}${x0+x*(x1-x0)} ${y0-scale*fn(x)}`}).join(' ')}
function draw(e,p,t,r){let s='';const rad=d=>d*Math.PI/180;
switch(e.id){
case'projectile':{const maxX=r.range*1.12,maxY=r.H*1.25,sx=x=>55+490*x/maxX,sy=y=>265-205*y/maxY; s=arrow(45,265,565,265,C.line)+arrow(55,275,55,35,C.line);s+=path(Array.from({length:101},(_,i)=>{const q=e.calc(p,r.T*i/100);return`${i?'L':'M'}${sx(q.x)} ${sy(q.y)}`}).join(' '),C.line,'stroke-dasharray="5 6"');s+=circle(sx(r.x),sy(r.y),9)+arrow(sx(r.x),sy(r.y),sx(r.x)+42,sy(r.y),C.blue)+arrow(sx(r.x),sy(r.y),sx(r.x),sy(r.y)-r.vy/p.v*65,C.amber)+text(72,47,'y, м')+text(515,291,'x, м')+text(75,80,'Траектория центра тела',C.muted)+text(75,102,'Горизонталь и вертикаль имеют разные масштабы',C.muted,11);break}
case'incline':{const a=rad(p.angle),L=250,x=100,y=60,ex=x+L*Math.cos(a),ey=y+L*Math.sin(a);s=path(`M${x} ${y}L${ex} ${ey}H${x}Z`,C.line)+text(80,285,`α = ${p.angle}° · ${r.a===0?'Трение удерживает тело':'Скольжение вниз'}`,C.muted);const bx=x+L*(r.s/p.length)*Math.cos(a),by=y+L*(r.s/p.length)*Math.sin(a);s+=`<g transform="translate(${bx} ${by}) rotate(${p.angle})">${rect(-20,-33,40,30,C.mint)}${arrow(0,-18,55,-18,C.blue)}${arrow(0,-18,-40,-18,C.amber)}</g>`+text(350,44,'↓ вдоль склона',C.blue)+text(350,66,'↑ трение',C.amber);break}
case'collision':{const end=e.calc(p,e.duration(p)),min=Math.min(-1,end.x1,end.x2)-1,max=Math.max(3,end.x1,end.x2)+1,x=v=>55+(v-min)/(max-min)*490;const a=x(r.x1)-28,b=x(r.x2)+28;s=line(35,215,565,215)+rect(a-28,155,56,48,C.mint)+rect(b-28,155,56,48,C.blue)+circle(a-15,210,5,C.muted)+circle(a+15,210,5,C.muted)+circle(b-15,210,5,C.muted)+circle(b+15,210,5,C.muted)+arrow(a,135,a+r.v1*16,135)+arrow(b,105,b+r.v2*16,105,C.blue)+text(45,55,`e = ${p.e} · ${t<r.tc?'До удара':'После удара'}`,C.ink,17)+text(45,280,`1: ${p.m1} кг     2: ${p.m2} кг     Потеря энергии при ударе: ${fmt(r.loss)} Дж`);break}
case'pendulum':{const len=155,a=rad(r.theta),x=300+len*Math.sin(a),y=65+len*Math.cos(a);s=line(230,60,370,60)+line(300,65,300,240,C.line,'stroke-dasharray="4 5"')+line(300,65,x,y,C.muted)+circle(x,y,15+3*p.mass)+circle(300,65,5,C.ink)+text(48,58,`l = ${fmt(p.length)} м`,C.ink)+text(48,84,'Нить и груз',C.muted)+arrow(x,y,x+Math.sign(r.v)*42,y,C.blue)+text(48,280,'Синяя стрелка: направление скорости · длина нити на схеме условна');break}
case'spring':{const x=300+r.x/p.A*120;s=rect(60,100,12,125,C.line)+line(60,225,550,225)+line(300,60,300,245,C.line,'stroke-dasharray="5 5"')+spring(72,x-24,170)+rect(x-24,140,48,60,C.mint)+arrow(x,115,x+r.v/(p.A*Math.sqrt(p.k/p.mass))*55,115,C.blue)+text(280,272,'x = 0')+text(48,48,`k = ${p.k} Н/м · m = ${p.mass} кг`,C.ink);break}
case'buoyancy':{const water=145,top=water-80+80*p.part/100;s=rect(165,water,270,130,'#204e5a')+path('M165 65V275H435V65',C.muted)+line(165,water,435,water,C.blue)+rect(265,top,70,80,C.mint,'fill-opacity=".7"')+arrow(285,top+40,285,top+40-r.F/Math.max(r.F,r.weight,1)*65,C.blue)+arrow(315,top+40,315,top+40+r.weight/Math.max(r.F,r.weight,1)*65,C.amber)+text(45,45,`Погружение ${p.part}%`,C.ink,17)+text(45,295,`${p.body<=p.rho?'Свободное равновесие: '+fmt(r.equilibrium)+'% погружения':'Без опоры тело будет тонуть'}`);break}
case'hydrostatic':{const y=85+180*p.depth/10;s=rect(155,85,290,185,'#204e5a')+path('M155 55V275H445V55',C.muted)+line(155,85,445,85,C.blue)+circle(300,y,12,C.amber)+line(312,y,480,y,C.amber)+text(450,Math.max(55,y-15),fmt(r.gauge)+' кПа',C.amber)+line(120,85,120,y,C.muted)+text(55,180,`${p.depth} м`)+text(165,45,'Датчик перепада давления',C.ink,17);break}
case'gas':{const top=245-p.V/50*170;s=path('M170 55V260H430V55',C.muted)+rect(175,top,250,255-top,'#284d49')+rect(165,top-12,270,12,C.mint)+rect(293,30,14,Math.max(1,top-42),C.muted);for(let i=0;i<24;i++)s+=circle(188+(i*83%222),top+12+(i*37%100)/100*Math.max(5,240-top),3,C.blue);s+=text(45,290,`V = ${p.V} л · T = ${p.T} К · p = ${fmt(r.pressure)} кПа`);break}
case'heating':{const T=Math.min(90,r.T),y=250-(T-10)/80*150;s=path('M170 60V255H370V60',C.muted)+rect(175,110,190,140,'#204e5a')+path('M190 240H350M190 232H350',C.amber)+rect(440,75,18,180,C.line)+rect(445,y,8,255-y,C.amber)+circle(449,260,16,C.amber)+text(415,48,fmt(r.T)+' °C',C.ink,18)+text(190,290,`Нагреватель ${p.power} Вт`);break}
case'mixing':{s=rect(60,90,120,95,'#734b3e')+rect(420,90,120,95,'#204e5a')+text(60,65,`${p.hotMass} кг · ${p.hot} °C`,C.amber)+text(420,65,`${p.coldMass} кг · ${p.cold} °C`,C.blue)+arrow(185,150,250,205,C.amber)+arrow(415,150,350,205,C.blue)+rect(240,210,120,65,'#3c6558')+text(255,250,fmt(r.T)+' °C',C.mint,22)+text(210,302,'Тепловое равновесие');break}
case'ohm':case'circuits':case'capacitor':{const parallel=e.id==='circuits'&&p.mode===2;s=path('M110 150V65H500V260H110V190',C.line)+line(87,150,133,150,C.amber)+line(96,190,124,190,C.amber)+text(45,175,`${p.U} В`,C.amber)+text(92,135,'+',C.amber)+text(92,215,'−',C.amber);if(e.id==='capacitor'){s+=rect(260,51,70,28,C.mint)+text(265,40,`${p.resistance} кОм`)+line(480,150,520,150,C.blue)+line(480,177,520,177,C.blue)+line(500,152,500,175,'#102b25','stroke-width="8"')+text(395,205,`${p.C} мкФ`,C.blue)+text(200,285,`Uс = ${fmt(r.Uc)} В · I = ${fmt(r.I)} мА`)}else if(e.id==='ohm'){s+=rect(250,51,90,28,C.mint)+text(260,40,`${p.resistance} Ом`)+circle(500,160,22,C.blue)+text(492,166,'A','#102b25',18)+text(220,287,`I = ${fmt(r.I)} А`,C.mint,18)}else{s+=rect(245,51,80,28,C.mint)+text(245,40,`R₁ = ${p.r1} Ом`);if(parallel)s+=path('M180 65V165H420V65',C.line)+rect(245,151,80,28,C.blue)+text(245,202,`R₂ = ${p.r2} Ом`);else s+=rect(365,51,80,28,C.blue)+text(365,40,`R₂ = ${p.r2} Ом`);s+=text(180,290,`U₁ = ${fmt(r.U1)} В · U₂ = ${fmt(r.U2)} В`)}break}
case'induction':{for(let x=120;x<=480;x+=90)for(let y=85;y<=250;y+=55)s+=`<circle cx="${x}" cy="${y}" r="7" fill="none" stroke="${C.line}"/>`+line(x-3,y-3,x+3,y+3,C.line)+line(x-3,y+3,x+3,y-3,C.line);const width=150*Math.cos(rad(r.angle));s+=path(`M${300-width/2} 110L${300+width/2} 110V230H${300-width/2}Z`,C.mint)+line(300,65,300,265,C.amber,'stroke-dasharray="4 5"')+text(45,45,'B ⊗ · вид вдоль магнитного поля',C.ink,17)+text(45,295,`Φ = ${fmt(r.flux)} мВб · ε = ${fmt(r.emf)} В`);break}
case'wave':case'standing':{s=line(45,160,555,160,C.line);if(e.id==='wave'){s+=path(wavePath(x=>p.A*Math.sin(2*Math.PI*(p.f*t-p.f*x*10/p.speed))),C.mint)+circle(45+510*p.probe/10,160-65*r.y,8,C.amber)+arrow(450,55,535,55,C.blue)+text(45,295,'Частица колеблется на месте · волна переносит энергию');for(let i=0;i<=10;i+=2)s+=text(40+51*i,255,i+' м')}else{s+=path(wavePath(x=>Math.sin(p.n*Math.PI*x)*r.y),C.mint);for(let i=0;i<=p.n;i++)s+=circle(45+510*i/p.n,160,5,C.amber);s+=line(45,70,45,245,C.muted)+line(555,70,555,245,C.muted)+text(45,45,`${p.n}-я гармоника · f = ${fmt(r.f)} Гц`,C.ink,17)+text(45,295,'Жёлтые точки — узлы. Нормированная амплитуда.')};break}
case'refraction':{const a=rad(p.angle),b=rad(r.angle2||0),cx=300,cy=160,len=130;s=rect(30,160,540,130,'#204e5a')+line(30,160,570,160,C.muted)+line(300,30,300,295,C.muted,'stroke-dasharray="5 5"')+arrow(cx-len*Math.sin(a),cy-len*Math.cos(a),cx,cy,C.amber)+arrow(cx,cy,cx+len*Math.sin(a),cy-len*Math.cos(a),C.amber);if(!r.tir)s+=arrow(cx,cy,cx+len*Math.sin(b),cy+len*Math.cos(b),C.blue);s+=text(45,55,`n₁ = ${p.n1}`,C.ink)+text(45,270,`n₂ = ${p.n2}`,C.ink)+text(350,290,r.tir?'Полное внутреннее отражение':`β = ${fmt(r.angle2)}°`,r.tir?C.amber:C.blue)+text(315,42,'нормаль',C.muted,11);break}
case'lens':{const q=r.q,ext=Math.max(p.d,p.f*2,q===null?0:Math.abs(q)),scale=Math.min(7,240/(ext*1.1)),heightScale=Math.min(15,100/Math.max(p.height,Math.abs(r.imageHeight||0))),cx=300,cy=165,xo=cx-p.d*scale,yo=cy-p.height*heightScale;s=line(35,cy,565,cy,C.line)+path(`M300 55Q318 165 300 275Q282 165 300 55`,C.blue)+arrow(xo,cy,xo,yo,C.mint)+text(xo,cy+22,'Предмет',C.mint,11);for(const sign of[-1,1])s+=circle(cx+sign*p.f*scale,cy,4,C.amber)+text(cx+sign*p.f*scale-4,cy+22,sign<0?'−F':'F',C.amber,11);const right=550,rayY=yo+(right-cx)*(cy-yo)/(p.f*scale);s+=path(`M${xo} ${yo}H${cx}L${right} ${rayY}`,C.amber)+path(`M${xo} ${yo}L${right} ${cy+(right-cx)*(cy-yo)/(p.d*scale)}`,C.mint);if(q!==null){const xi=cx+q*scale,yi=cy-r.imageHeight*heightScale;s+=arrow(xi,cy,xi,yi,C.pink)+text(xi-25,cy+40,'Изображение',C.pink,11);if(q<0)s+=path(`M${cx} ${yo}L${xi} ${yi}M${cx} ${cy}L${xi} ${yi}`,C.muted,'stroke-dasharray="5 5"')}s+=text(40,35,q===null?'Предмет в фокусе: лучи параллельны':q>0?'Действительное, перевёрнутое':'Мнимое, прямое',C.ink,15)+text(40,305,'Оси масштабируются независимо · лучи обрезаны границей схемы',C.muted,11);break}
case'photoelectric':{s=rect(255,85,25,180,C.line)+text(210,290,'Металл',C.muted)+path(wavePath(x=>.15*Math.sin(x*45),55,240,155,65),C.amber)+arrow(220,155,250,155,C.amber)+text(45,65,`hν = ${fmt(r.photon)} эВ`,C.amber);if(r.emits){s+=arrow(285,160,450,120,C.blue)+circle(450,120,8,C.blue)+text(350,200,`Kmax = ${fmt(r.K)} эВ`,C.blue)}else s+=text(320,165,'Эмиссии нет',C.ink,18);s+=text(320,240,`Aвых = ${p.work} эВ`);break}
case'decay':{const active=Math.round(r.remaining);for(let i=0;i<100;i++)s+=circle(85+(i%20)*23,80+Math.floor(i/20)*36,6,i<active?C.mint:'#38584e');s+=text(65,40,`Осталось ${fmt(r.remaining)}%`,C.ink,18)+text(65,285,'1 точка ≈ 1% исходного ансамбля. Показано среднее.');break}
}
return`<svg viewBox="0 0 600 330" role="img" aria-label="${esc(e.title)}: схема опыта" xmlns="http://www.w3.org/2000/svg"><defs><marker id="labArrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto-start-reverse"><path d="M0 0L7 3.5L0 7Z" fill="context-stroke"/></marker><pattern id="labGrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#2a483e" stroke-width=".5"/></pattern><clipPath id="labBounds"><rect width="600" height="330"/></clipPath></defs><rect width="600" height="330" fill="#102b25"/><rect width="600" height="330" fill="url(#labGrid)"/><g clip-path="url(#labBounds)">${s}</g></svg>`;
}
window.matclubLabScenes={draw};
})();
